-- ---------------------------------------------------------------------------
-- Hand-written additions
-- ---------------------------------------------------------------------------

-- Exactly one polymorphic target per comment.
ALTER TABLE "comments" ADD CONSTRAINT "comments_one_target"
  CHECK (num_nonnulls("review_id", "anime_id", "movie_id") = 1);

-- Scores are 0..10 with one decimal.
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_score_range" CHECK ("score" >= 0 AND "score" <= 10);
ALTER TABLE "anime" ADD CONSTRAINT "anime_score_range" CHECK ("score" >= 0 AND "score" <= 10);
ALTER TABLE "movie" ADD CONSTRAINT "movie_score_range" CHECK ("score" >= 0 AND "score" <= 10);

-- Trigram indexes power the ILIKE '%term%' searches used by list/search pages.
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX "reviews_title_trgm" ON "reviews" USING gin ("title" gin_trgm_ops);
CREATE INDEX "albums_title_trgm" ON "albums" USING gin ("title" gin_trgm_ops);
CREATE INDEX "albums_artist_trgm" ON "albums" USING gin ("artist" gin_trgm_ops);
CREATE INDEX "anime_title_trgm" ON "anime" USING gin ("title" gin_trgm_ops);
CREATE INDEX "movie_title_trgm" ON "movie" USING gin ("title" gin_trgm_ops);
